#include <omp.h>
#include <array>
#include <vector>
#include <cstddef>

using std::size_t;

void binsBy10Count(std::vector<double> const& x, std::array<size_t, 10> &bins) {
    bins.fill(0);

    #pragma omp parallel default(none) shared(x, bins)
    {
        std::array<size_t, 10> local_bins{};
        local_bins.fill(0);

        #pragma omp for schedule(static)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(x.size()); ++i) {
            const double v = x[static_cast<size_t>(i)];

            // Values are guaranteed to be in [0, 100]. Put 100 into the last bin.
            size_t bin = (v >= 100.0) ? 9u : static_cast<size_t>(v / 10.0);
            ++local_bins[bin];
        }

        #pragma omp critical
        {
            for (size_t b = 0; b < 10; ++b) {
                bins[b] += local_bins[b];
            }
        }
    }
}
